#!/usr/bin/env node
/* eslint-disable no-console */

/*
 * End-to-end Windows NSIS packaging sanity check.
 *
 * P1-4 deliverable. Runs the same stages as ``npm run dist:win:offline`` but
 * stops before the actual ``electron-builder`` invocation so it can be
 * executed in CI environments that lack PortableGit / signtool. It verifies
 * that:
 *
 *   1. The brand icons generated by ``scripts/generate-app-icons.py`` are
 *      present at every size referenced from ``electron-builder.json``.
 *   2. The NSIS installer BMPs generated by
 *      ``scripts/generate-nsis-brand-assets.cjs`` are valid 24-bit BMPs.
 *   3. The ``appUpdateCoordinator`` + ``installWindowsNsis`` wiring still
 *      points at a real PowerShell launcher (no placeholder shell).
 *
 * Exit codes:
 *   0 - every required asset is present and consistent.
 *   1 - at least one asset is missing or malformed.
 */

const fs = require('node:fs');
const path = require('node:path');

const projectRoot = process.env.ZHIYUAN_PACKAGE_ROOT
  ? path.resolve(process.env.ZHIYUAN_PACKAGE_ROOT)
  : path.resolve(__dirname, '..');

const PNG_SIZES = [16, 24, 32, 48, 64, 128, 256, 512, 1024];
const REQUIRED_FILES = [
  ['build/icons/png/256x256.png', 'macOS dock / Linux PNG bundle'],
  ['build/icons/win/icon.ico', 'Windows .ico container (multi-size)'],
  ['build/icons/mac/icon.icns', 'macOS .icns bundle'],
  ['build/installer-assets/installerHeader.bmp', 'NSIS installer header BMP'],
  ['build/installer-assets/installerSidebar.bmp', 'NSIS sidebar BMP'],
  ['build/installer-assets/uninstallerSidebar.bmp', 'NSIS uninstaller sidebar BMP'],
];

function check(label, ok, detail) {
  const marker = ok ? '[ OK ]' : '[FAIL]';
  console.log(`${marker} ${label}${detail ? '  -- ' + detail : ''}`);
  return ok;
}

function expectExists(rel) {
  const full = path.join(projectRoot, rel);
  if (!fs.existsSync(full)) return { ok: false, detail: 'missing' };
  const stat = fs.statSync(full);
  if (stat.size === 0) return { ok: false, detail: 'empty' };
  return { ok: true, size: stat.size };
}

function checkBmpHeader(rel) {
  const full = path.join(projectRoot, rel);
  const buf = fs.readFileSync(full);
  if (buf.length < 54) return { ok: false, detail: 'BMP too small' };
  if (buf.toString('ascii', 0, 2) !== 'BM') {
    return { ok: false, detail: 'missing BM signature' };
  }
  const bitsPerPixel = buf.readUInt16LE(28);
  if (bitsPerPixel !== 24) {
    return { ok: false, detail: `bpp=${bitsPerPixel}, expected 24` };
  }
  return { ok: true };
}

function checkIcoContainer(rel) {
  const full = path.join(projectRoot, rel);
  const buf = fs.readFileSync(full);
  if (buf.length < 22) return { ok: false, detail: 'ICO header too small' };
  if (buf.readUInt16LE(0) !== 0) {
    return { ok: false, detail: 'reserved word must be 0' };
  }
  if (buf.readUInt16LE(2) !== 1) {
    return { ok: false, detail: 'type must be 1 (icon)' };
  }
  const count = buf.readUInt16LE(4);
  if (count < 4) return { ok: false, detail: `only ${count} images` };
  return { ok: true, count };
}

function checkIcnsContainer(rel) {
  const full = path.join(projectRoot, rel);
  const buf = fs.readFileSync(full);
  if (buf.length < 8) return { ok: false, detail: 'ICNS header too small' };
  if (buf.toString('ascii', 0, 4) !== 'icns') {
    return { ok: false, detail: 'missing icns magic' };
  }
  return { ok: true, size: buf.length };
}

function checkUpdateHandoff() {
  const installerPath = path.join(
    projectRoot,
    'src/main/libs/appUpdateInstaller.ts',
  );
  if (!fs.existsSync(installerPath)) {
    return { ok: false, detail: 'installer module missing' };
  }
  const src = fs.readFileSync(installerPath, 'utf8');
  const usesPs1 = src.includes('powershell.exe') && src.includes('.ps1');
  const usesVbs = src.includes('wscript.exe') && src.includes('.vbs');
  const usesNsis = src.includes('Start-Process') && src.includes('NSIS finish');
  return {
    ok: usesPs1 && usesVbs && usesNsis,
    detail: `ps1=${usesPs1} vbs=${usesVbs} nsis=${usesNsis}`,
  };
}

function main() {
  console.log('P1-4 Windows packaging asset audit');
  console.log('==================================');

  let pass = true;

  for (const [rel, label] of REQUIRED_FILES) {
    const r = expectExists(rel);
    pass = check(`${label}  (${rel})`, r.ok, r.detail) && pass;
  }

  for (const size of PNG_SIZES) {
    const rel = `build/icons/png/${size}x${size}.png`;
    const r = expectExists(rel);
    pass = check(`PNG ${size}x${size}`, r.ok, r.detail) && pass;
  }

  const bmp = checkBmpHeader('build/installer-assets/installerHeader.bmp');
  pass = check('Header BMP is 24-bit', bmp.ok, bmp.detail) && pass;
  const sidebar = checkBmpHeader('build/installer-assets/installerSidebar.bmp');
  pass = check('Sidebar BMP is 24-bit', sidebar.ok, sidebar.detail) && pass;
  const uninstaller = checkBmpHeader(
    'build/installer-assets/uninstallerSidebar.bmp',
  );
  pass = check('Uninstaller BMP is 24-bit', uninstaller.ok, uninstaller.detail) && pass;

  const ico = checkIcoContainer('build/icons/win/icon.ico');
  pass = check('Windows .ico multi-size container', ico.ok, ico.detail) && pass;

  const icns = checkIcnsContainer('build/icons/mac/icon.icns');
  pass = check('macOS .icns bundle', icns.ok, icns.detail) && pass;

  const handoff = checkUpdateHandoff();
  pass = check(
    'appUpdateInstaller still uses PowerShell + VBS NSIS handoff',
    handoff.ok,
    handoff.detail,
  ) && pass;

  console.log('==================================');
  console.log(pass ? 'PASS - Windows packaging prerequisites OK.' : 'FAIL - see above.');
  process.exit(pass ? 0 : 1);
}

main();
